function asProgress(s){return s.operator?(s.steps.filter(x=>x.status==='done').length+'步已执行 · '+(s.rounds||0)+'轮分析'+(s.phase?' · '+s.phase:'')):((s.cursor||0)+'/'+s.steps.length+' 步')}

ask=asAsk;
renderGuide=function(){const el=$('#guide');if(!el.classList.contains('o'))return;el.classList.add('as-panel');const focus=document.activeElement?.id==='as-input',caret=$('#as-input')?.selectionStart,s=asSession(),busy=!!AS.ac,active=s?.steps?.[s.cursor];
 el.innerHTML=`<h3>${icon('bot',22)}AI 操作助手<button class="x" data-close="guide" aria-label="收起并暂停助手">${icon('close')}</button></h3><div id="gl">${renderAssistantWelcome(RelayAssistantCopy.welcome)}${AS.localReply?`<p class="ac">${esc(AS.localReply)}</p>`:''}${s?`<details class="as-request"><summary>${esc((s.followups?.at(-1)||s.request).slice(0,64))}${(s.followups?.at(-1)||s.request).length>64?'…':''}</summary><p>${esc(s.request)}</p>${(s.followups||[]).map((text,i)=>`<p><b>更新 ${i+1}：</b>${esc(text)}</p>`).join('')}</details>${s.operator&&s.status==='completed'?`<details class="as-completion"><summary>${esc((s.reply||'已完成需求').split('\n')[0].slice(0,110))}</summary><p class="as-reply as-final">${esc(s.reply)}</p></details>`:`<p class="as-reply">${esc(s.reply||'正在理解目标与软件状态…')}</p>`}${s.binding?`<small class="lab">操作模型：${esc(s.binding.model)}</small>`:''}<div class="as-status" role="status">${esc(({planning:'理解与分析',ready:'准备执行',running:'正在执行',waiting:'等待你的操作',paused:'已暂停',failed:'未完成',completed:'已完成'})[s.status]||s.status)} · ${asProgress(s)}${s.runStatus?'<br>'+esc(s.runStatus):''}</div>${s.question?`<p class="ac">${esc(s.question)}</p>`:''}${s.reason?`<p class="lab">${esc(s.reason)}</p>`:''}<ol class="as-steps">${s.steps.map((x,i)=>({x,i})).filter(({i})=>AS.showAll||Math.abs(i-(s.cursor||0))<=3).map(({x,i})=>`<li data-as-step="${x.id}" data-state="${x.status}"><span>${x.status==='done'?'✓':x.status==='running'?'●':i+1}</span><div><b>${esc(x.label)}</b>${x.result?.message?`<small>${esc(x.result.message)}</small>`:''}${x.result&&(x.result.projectId||x.result.boardId||x.result.fileId||x.result.linkId)?`<button class="as-jump" data-as-locate="${x.id}">定位结果</button>`:''}</div></li>`).join('')}</ol>${s.steps.length>6?`<button class="as-jump" data-as-all>${AS.showAll?'收起已完成步骤':'查看全部 '+s.steps.length+' 步'}</button>`:''}${s.status==='waiting'&&active?`<div class="ac"><p>${esc(active.label)}</p>${active.effect==='model'?'<p class="lab">将使用项目已绑定的模型；可以在房间随时暂停。</p>':''}<button data-as-continue>${icon('play',14)}${active.effect==='model'?'确认本步并开工':active.effect==='file-picker'?'选择本机文件':'确认交给现有授权'}</button></div>`:''}${s.status==='paused'||s.status==='failed'||s.status==='waiting'&&!active&&!s.question?`<button data-as-continue>${icon('play',14)}继续未完成步骤</button>`:''}${AS.recordOpen?`<details open class="as-record"><summary>本次执行记录 JSON</summary><pre data-as-record>${esc(JSON.stringify(s,null,2))}</pre></details>`:''}${s.status==='completed'?`<div class="row"><button data-as-results>${icon('fit',14)}查看画板成果</button><button data-as-export>${icon('download',14)}导出执行记录</button><button data-as-undo>${icon('undo',14)}撤销上一步编辑</button></div>`:''}`:'<p>例如：读取文件，组织项目与模型团队，设置共享并保存成果；也可以检查任务状态、调整软件界面或接续先前工作。</p>'}</div><details class="as-model"><summary>执行设置与可用能力</summary><label>任务记录<select data-as-history ${busy?'disabled':''}>${state.assistantSessions.slice().reverse().map(x=>`<option value="${x.id}" ${s?.id===x.id?'selected':''}>${esc((x.demo?'本地示范 · ':'')+x.request.slice(0,36))}</option>`).join('')}</select></label><label>已保存的模型连接<select data-as-binding><option value="">自动选用已保存的模型</option>${AS.profiles.map(p=>`<option value="${p.id}" ${state.prefs.assistantBinding?.connectionId===p.id?'selected':''}>${esc(p.name+' · '+p.defaultModel)}</option>`).join('')}</select></label><p class="lab">成员仍使用各自绑定模型。文件选择、开工和站点授权会在对应步骤等你确认。</p><div class="row"><button data-act="models.open">连接设置</button><button data-as-catalog>查看全部可控组件</button></div></details><div class="as-compose"><textarea id="as-input" aria-label="给AI助手的需求" placeholder="描述要完成的事，我来操作软件…">${esc(AS.draft)}</textarea><div class="row">${busy?`<button data-as-pause>${icon('pause',14)}暂停</button><button data-as-steer>更新要求</button>`:`<button data-as-send>${icon('send',14)}执行需求</button>`}<button data-as-feature>亮点工具实操</button></div></div>`;dmDecorate();if(focus){$('#as-input').focus();$('#as-input').setSelectionRange(caret,caret)}void asProfiles()};
const asTopBase=renderTop;renderTop=function(){asTopBase();const b=$('#gb [data-a=guide]');if(b){b.innerHTML=icon('bot',16)+'<span class="memphis-label">助手</span>';b.setAttribute('aria-label','AI 助手');b.title='AI 助手'}};
function asLocate(r){if(!r)return;asPause();if(r.fileId)return act('reader.open',{fileId:r.fileId});if(r.runId)return openPan('collaboration',r.runId);if(r.linkId)return act('link.open',{linkId:r.linkId});if(r.projectId&&P(r.projectId)){const p=P(r.projectId);state.activeBoard=p.boardId;state.room=null;state.sel=p.id;fit([p]);renderAll();return}if(r.boardId)act('board.switch',{boardId:r.boardId})}
function asExport(){AS.recordOpen=!AS.recordOpen;renderGuide();if(AS.recordOpen){const el=$('#gl');el.scrollTop=el.scrollHeight}}
const asGuideDecorateBase=renderGuide;renderGuide=function(){asGuideDecorateBase();const s=asSession();for(const dialog of [skillbook,modelConnect]){dialog.querySelector('.as-modal-status')?.remove();if(dialog.open&&s&&(AS.ac||s.status==='waiting'))dialog.insertAdjacentHTML('beforeend',`<div class="as-modal-status"><span>助手：${esc(s.steps[s.cursor]?.label||'正在处理')}</span><button data-as-pause>暂停助手</button><button data-as-return>返回助手</button></div>`)}};
for(const name of ['assistant.bind','assistant.bindGroup','assistant.start','assistant.read','assistant.refine','assistant.library','auth.request'])ACT[name]=a=>{const s={id:'as'+uid(),boardId:state.activeBoard,request:CAT.find(c=>c[0]===name)[1],steps:[{id:'s1',name,label:CAT.find(c=>c[0]===name)[1],args:a,status:'pending',effect:['assistant.start','assistant.refine'].includes(name)?'model':name==='auth.request'?'authorization':'local'}],cursor:0,status:'ready',createdAt:Date.now()};state.assistantSessions.push(s);AS.current=s.id;$('#guide').classList.add('o');void asExecute(s);return'已交给内置助手，进度在助手中显示'};
document.addEventListener('input',e=>{if(e.target.id==='as-input')AS.draft=e.target.value});
document.addEventListener('change',e=>{if(e.target.hasAttribute('data-as-history')){if(AS.ac)return;AS.current=e.target.value;AS.recordOpen=false;renderGuide();return}if(e.target.hasAttribute('data-as-binding')){const p=AS.profiles.find(p=>p.id===e.target.value);state.prefs.assistantBinding=p?{connectionId:p.id,model:p.defaultModel}:null;save()}});
document.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;if(t.hasAttribute('data-as-send')){const text=$('#as-input').value.trim();if(text){const s=asSession();if(s?.operator&&['waiting','paused','failed'].includes(s.status))void asSteer(text);else void asAsk(text)}}else if(t.hasAttribute('data-as-steer')){const text=$('#as-input').value.trim();if(text)void asSteer(text);else hint('先写下新的要求')}else if(t.hasAttribute('data-as-pause'))asPause();else if(t.hasAttribute('data-as-continue')){const s=asSession();if(s?.operator||s?.steps.length)void asExecute(s,true);else if(s)void asAsk(s.request)}else if(t.hasAttribute('data-as-all')){AS.showAll=!AS.showAll;renderGuide()}else if(t.hasAttribute('data-as-locate'))asLocate(asSession()?.steps.find(x=>x.id===t.dataset.asLocate)?.result);else if(t.hasAttribute('data-as-return')){asCloseAux();$('#guide').classList.add('o');renderGuide()}else if(t.hasAttribute('data-as-export'))asExport();else if(t.hasAttribute('data-as-undo'))act('undo',{});else if(t.hasAttribute('data-as-results')){asCloseAux();$('#guide').classList.remove('o');act('view.fit',{})}else if(t.hasAttribute('data-as-catalog')){AS.localReply='可控组件：'+CAT.map(c=>c[1]).join('、');renderGuide()}else if(t.hasAttribute('data-as-feature')){if(typeof featureBegin==='function')featureBegin()}else if(t.dataset.close==='guide')asPause()},true);

const asRestoreBase=restore;restore=function(str){const journal=state.assistantSessions,course=state.featureTour;asRestoreBase(str);state.assistantSessions=journal;state.featureTour=course;save();renderGuide()};
/* ASSISTANT_END */
